5, 0.366);\r\n\r\n}\r\n\r\n/* Optional styling for icon (checked) */\r\n.selected::before {\r\n    content: \"✔\";\r\n    margin-right: 8px;\r\n}\r\n\r\n\r\n\r\n\r\n\r\n\r\n.formTableBookList {\r\n    margin-top: 30px;\r\n    height: auto;\r\n    max-height: 367px;\r\n    overflow: auto;\r\n    min-width: 100%;\r\n    margin-bottom: 30px;\r\n\r\n    border-bottom: 1px solid #ddd;\r\n}\r\n\r\n.formTableList {\r\n    border-collapse: separate;\r\n    border-spacing: 0;\r\n}\r\n\r\n.formTableList2thead {\r\n    position: sticky;\r\n    top: 0px;\r\n    border-top: 1px solid red;\r\n}\r\n\r\n.formTableList2thead.active {\r\n    background-color: lightblue;\r\n}\r\n\r\n.filter-containers {\r\n    padding: 20px;\r\n    border: 1px solid #ddd;\r\n    border-radius: 3px;\r\n    background: linear-gradient(0deg, rgb(246 246 246) 0%, rgba(255, 255, 255, 1) 100%);\r\n    align-items: start;\r\n    /* Align items at the start vertically */\r\n    margin-bottom: 60px;\r\n    margin-top: 30px;\r\n}\r\n\r\n.filter-container {\r\n    display: grid;\r\n    grid-template-columns: 3fr 0fr;\r\n    /* Left side with filter items, right side with button */\r\n    margin-bottom: 30px;\r\n}\r\n\r\n.filter-items {\r\n    display: grid;\r\n    grid-template-columns: repeat(3, 1fr);\r\n    /* 3 columns for filter items */\r\n    gap: 20px 7%;\r\n}\r\n\r\n.filter-item {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 5px;\r\n    /* Reduced space between label and input */\r\n}\r\n\r\n.filter-item label {\r\n    width: 25%;\r\n    font-weight: bold;\r\n    font-size: 14px;\r\n    color: #333;\r\n}\r\n\r\n.filter-item input {\r\n    flex: 1;\r\n    padding: 8px;\r\n    border: 1px solid #ccc;\r\n    border-radius: 4px;\r\n    font-size: 14px;\r\n    box-sizing: border-box;\r\n}\r\n\r\n.button-container {\r\n    display: flex;\r\n    align-items: center;\r\n    /* 세로(위아래) 가운데 정렬 */\r\n    justify-content: flex-end;\r\n    /* 가로 가운데 정렬 (필요 시) */\r\n}\r\n\r\n.search-btn {\r\n    paddi